-- 0142: Jujutsu Kaisen — Toji WOLLTE Megumi an die Zenin verkaufen (Gojo verhinderte
-- es), Sukunas offene Domäne deckt ein riesiges Gebiet ab, keine ganze Stadt. Idempotent.
update question_translations set explanation = 'Toji planned to sell his son to the Zenin family – Gojo prevented it.' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Aus welcher der drei großen Familien stammt Megumi ursprünglich?');
update question_translations set explanation = 'Toji quería vender a su hijo a la familia Zenin, pero Gojo lo impidió.' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Aus welcher der drei großen Familien stammt Megumi ursprünglich?');
